"""Validation, wire values, and synchronized in-memory request state."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone
import json
import math
import re
import threading
import time
from urllib.parse import urlsplit


class APIError(Exception):
    """An expected API failure; unexpected exceptions remain internal errors."""

    def __init__(self, status: int, code: str, message: str, headers: dict | None = None):
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message
        self.headers = {} if headers is None else headers

    def body(self) -> dict:
        return {"error": {"code": self.code, "message": self.message}}


def json_bytes(value: object) -> bytes:
    return json.dumps(value, separators=(",", ":"), ensure_ascii=True).encode("utf-8")


def _reject_constant(value: str) -> None:
    raise ValueError("Non-JSON number: " + value)


def decode_json(body: bytes) -> dict:
    """Decode an object only; request size/auth/route checks belong to HTTP."""
    try:
        value = json.loads(body.decode("utf-8"), parse_constant=_reject_constant)
    except (UnicodeDecodeError, ValueError, RecursionError):
        raise APIError(400, "invalid_json", "Expected a UTF-8 JSON object") from None
    if not isinstance(value, dict):
        raise APIError(400, "invalid_json", "Expected a JSON object")
    return value


_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)
_TIMESTAMP = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z")
_SLUG = re.compile(r"[A-Za-z0-9_-]{3,32}")


def parse_timestamp(value: str) -> int:
    if not isinstance(value, str) or _TIMESTAMP.fullmatch(value) is None:
        raise APIError(400, "invalid_request", "Invalid UTC timestamp")
    try:
        instant = datetime(
            int(value[:4]), int(value[5:7]), int(value[8:10]),
            int(value[11:13]), int(value[14:16]), int(value[17:19]),
            tzinfo=timezone.utc,
        )
    except ValueError:
        raise APIError(400, "invalid_request", "Invalid UTC timestamp") from None
    return (instant - _EPOCH) // timedelta(seconds=1)


def format_timestamp(value: int) -> str:
    instant = _EPOCH + timedelta(seconds=value)
    return (
        f"{instant.year:04d}-{instant.month:02d}-{instant.day:02d}"
        f"T{instant.hour:02d}:{instant.minute:02d}:{instant.second:02d}Z"
    )


def valid_slug(value: object) -> bool:
    """Syntax only: the reserved healthz slug is a later resource conflict."""
    return isinstance(value, str) and _SLUG.fullmatch(value) is not None


def validate_url(value: str) -> str:
    if (
        not isinstance(value, str) or not value or len(value) > 2048
        or any(character.isspace() or ord(character) < 0x21 or ord(character) == 0x7F
               for character in value)
    ):
        raise APIError(400, "invalid_request", "Invalid URL")
    try:
        parts = urlsplit(value)
        valid = parts.scheme.lower() in ("http", "https") and bool(parts.hostname)
    except ValueError:
        valid = False
    if not valid:
        raise APIError(400, "invalid_request", "Invalid URL")
    return value


def validate_create(body: dict) -> dict:
    if (
        not isinstance(body, dict) or "url" not in body
        or set(body) - {"url", "slug", "expires_in"}
    ):
        raise APIError(400, "invalid_request", "Invalid link fields")
    validate_url(body["url"])
    if "slug" in body and not valid_slug(body["slug"]):
        raise APIError(400, "invalid_request", "Invalid slug")
    if "expires_in" in body and (
        type(body["expires_in"]) is not int or not 1 <= body["expires_in"] <= 31536000
    ):
        raise APIError(400, "invalid_request", "Invalid expires_in")
    return body


def validate_clock(body: dict) -> int:
    if not isinstance(body, dict) or set(body) != {"now"}:
        raise APIError(400, "invalid_request", "Expected only now")
    return parse_timestamp(body["now"])


class Clock:
    """None selects real time; fake_now and set() use parsed integer seconds."""

    def __init__(self, fake_now: int | None = None):
        self._fake_now = fake_now
        self._lock = threading.Lock()
        self.is_fake = fake_now is not None

    def now(self) -> int:
        with self._lock:
            return self._fake_now if self.is_fake else math.floor(time.time())

    def set(self, now: int) -> int:
        with self._lock:
            if not self.is_fake:
                raise APIError(404, "not_found", "Fake clock is disabled")
            self._fake_now = now
            return now


class RateLimiter:
    """Count every check, retaining historical windows for backward fake time."""

    def __init__(self, limit: int = 60):
        if type(limit) is not int or limit < 1:
            raise ValueError("Rate limit must be a positive integer")
        self._limit = limit
        self._counts: dict[tuple[str, int], int] = {}
        self._lock = threading.Lock()

    def check(self, token_hash: str, now: int) -> None:
        window_start = now - now % 60
        key = (token_hash, window_start)
        with self._lock:
            count = self._counts.get(key, 0) + 1
            self._counts[key] = count
        if count > self._limit:
            raise APIError(
                429, "rate_limited", "Rate limit exceeded",
                {"Retry-After": str(window_start + 60 - now)},
            )

"""One locked SQLite connection; owners are authenticated token digests."""

from __future__ import annotations

import hashlib
import re
import secrets
import sqlite3
import threading

from .domain import APIError, format_timestamp, validate_create


_SCHEMA = """
PRAGMA user_version = 1;
CREATE TABLE IF NOT EXISTS tokens (
  token_hash TEXT PRIMARY KEY,
  created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS links (
  slug TEXT PRIMARY KEY,
  url TEXT NOT NULL,
  token_hash TEXT NOT NULL REFERENCES tokens(token_hash),
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  clicks INTEGER NOT NULL DEFAULT 0,
  last_clicked_at INTEGER);
"""
_ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789"
_TOKEN = re.compile(r"lv_[0-9a-f]{32}")


def _digest(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def _link(row: sqlite3.Row, base_url: str) -> dict:
    return {
        "slug": row["slug"],
        "url": row["url"],
        "short_url": f"{base_url}/{row['slug']}",
        "created_at": format_timestamp(row["created_at"]),
        "expires_at": (format_timestamp(row["expires_at"])
                       if row["expires_at"] is not None else None),
        "clicks": row["clicks"],
        "last_clicked_at": (format_timestamp(row["last_clicked_at"])
                            if row["last_clicked_at"] is not None else None),
    }


class Storage:
    def __init__(self, path: str):
        self._lock = threading.Lock()
        self._conn = sqlite3.connect(path, check_same_thread=False)
        with self._lock:
            try:
                self._conn.row_factory = sqlite3.Row
                self._conn.execute("PRAGMA foreign_keys = ON")
                self._conn.executescript(_SCHEMA)
                self._conn.commit()
            except Exception:
                self._conn.close()
                raise

    def close(self) -> None:
        with self._lock:
            self._conn.close()

    def issue_token(self, now: int) -> dict:
        token = "lv_" + secrets.token_hex(16)
        with self._lock, self._conn:
            self._conn.execute(
                "INSERT INTO tokens (token_hash, created_at) VALUES (?, ?)",
                (_digest(token), now),
            )
        return {"token": token, "created_at": format_timestamp(now)}

    def authenticate(self, token: str) -> str:
        if not isinstance(token, str) or _TOKEN.fullmatch(token) is None:
            raise APIError(401, "unauthorized", "Invalid token")
        token_hash = _digest(token)
        with self._lock:
            exists = self._conn.execute(
                "SELECT 1 FROM tokens WHERE token_hash = ?", (token_hash,),
            ).fetchone()
        if exists is None:
            raise APIError(401, "unauthorized", "Invalid token")
        return token_hash

    def create_link(self, token_hash: str, body: dict, now: int, base_url: str) -> dict:
        validate_create(body)
        with self._lock, self._conn:
            if "slug" in body:
                slug = body["slug"]
                if slug == "healthz" or self._exists(slug):
                    raise APIError(409, "slug_taken", "Slug is taken")
            else:
                for _ in range(5):
                    slug = "".join(secrets.choice(_ALPHABET) for _ in range(7))
                    if slug != "healthz" and not self._exists(slug):
                        break
                else:
                    raise APIError(500, "internal", "Could not generate a free slug")
            expires_at = now + body["expires_in"] if "expires_in" in body else None
            self._conn.execute(
                "INSERT INTO links (slug, url, token_hash, created_at, expires_at) "
                "VALUES (?, ?, ?, ?, ?)",
                (slug, body["url"], token_hash, now, expires_at),
            )
            row = self._conn.execute("SELECT * FROM links WHERE slug = ?", (slug,)).fetchone()
        return _link(row, base_url)

    def _exists(self, slug: str) -> bool:
        """Called only while holding the connection lock."""
        return self._conn.execute(
            "SELECT 1 FROM links WHERE slug = ?", (slug,),
        ).fetchone() is not None

    def list_links(self, token_hash: str, base_url: str) -> dict:
        with self._lock:
            rows = self._conn.execute(
                "SELECT * FROM links WHERE token_hash = ? ORDER BY created_at ASC, slug ASC",
                (token_hash,),
            ).fetchall()
        return {"links": [_link(row, base_url) for row in rows]}

    def get_link(self, token_hash: str, slug: str, base_url: str) -> dict:
        with self._lock:
            row = self._conn.execute(
                "SELECT * FROM links WHERE token_hash = ? AND slug = ?", (token_hash, slug),
            ).fetchone()
        if row is None:
            raise APIError(404, "not_found", "Link not found")
        return _link(row, base_url)

    def delete_link(self, token_hash: str, slug: str) -> None:
        with self._lock, self._conn:
            deleted = self._conn.execute(
                "DELETE FROM links WHERE token_hash = ? AND slug = ?", (token_hash, slug),
            ).rowcount
            if not deleted:
                raise APIError(404, "not_found", "Link not found")

    def resolve(self, slug: str, now: int) -> str:
        with self._lock, self._conn:
            row = self._conn.execute(
                "SELECT url, expires_at FROM links WHERE slug = ?", (slug,),
            ).fetchone()
            if row is None:
                raise APIError(404, "not_found", "Link not found")
            if row["expires_at"] is not None and now >= row["expires_at"]:
                raise APIError(410, "gone", "Link expired")
            self._conn.execute(
                "UPDATE links SET clicks = clicks + 1, last_clicked_at = ? WHERE slug = ?",
                (now, slug),
            )
            return row["url"]

from concurrent.futures import ThreadPoolExecutor
import json

import pytest

from linkvault import domain
from linkvault.domain import (
    APIError, Clock, RateLimiter, decode_json, format_timestamp, json_bytes,
    parse_timestamp, valid_slug, validate_clock, validate_create, validate_url,
)


def assert_error(status, code, operation):
    with pytest.raises(APIError) as caught:
        operation()
    assert (caught.value.status, caught.value.code) == (status, code)
    return caught.value


def test_compact_json_and_ordered_error():
    error = APIError(429, "rate_limited", "Wait", {"Retry-After": "50"})
    assert str(error) == "Wait"
    assert error.headers == {"Retry-After": "50"}
    assert json_bytes(error.body()) == b'{"error":{"code":"rate_limited","message":"Wait"}}'
    assert json_bytes({"z": "é", "a": None, "b": [1, True]}) == (
        b'{"z":"\\u00e9","a":null,"b":[1,true]}'
    )
    assert APIError(400, "invalid_request", "Bad").headers == {}


def test_decode_object_preserves_key_order():
    assert list(decode_json(b'{"url":"https://x","slug":"ABC"}')) == ["url", "slug"]
    assert decode_json('{"url":"https://x/é"}'.encode("utf-8"))["url"] == "https://x/é"
    assert decode_json(b"{}") == {}


@pytest.mark.parametrize("body", [
    b"", b"{", b"{} trailing", b"{\xff}", b"[]", b"null", b"true", b"1", b'"x"',
    b'{"x":NaN}', b'{"x":Infinity}', b'{"x":-Infinity}',
])
def test_decode_rejects_invalid_json_or_nonobject(body):
    assert_error(400, "invalid_json", lambda: decode_json(body))


@pytest.mark.parametrize("text,seconds", [
    ("1970-01-01T00:00:00Z", 0),
    ("1969-12-31T23:59:59Z", -1),
    ("0001-01-01T00:00:00Z", -62135596800),
    ("0100-01-01T00:00:00Z", -59011459200),
    ("2000-02-29T12:34:56Z", 951827696),
    ("9999-12-31T23:59:59Z", 253402300799),
])
def test_timestamp_strict_round_trip(text, seconds):
    assert parse_timestamp(text) == seconds
    assert type(parse_timestamp(text)) is int
    assert format_timestamp(seconds) == text


@pytest.mark.parametrize("value", [
