def test_timestamp_rejects_lexical_and_calendar_errors(value):
    assert_error(400, "invalid_request", lambda: parse_timestamp(value))


@pytest.mark.parametrize("value", ["abc", "ABC", "a_1", "_-Z", "a" * 32, "healthz", "Healthz"])
