@pytest.mark.parametrize("body", [
    {"url": "https://x"},
    {"url": "https://x", "slug": "healthz"},
    {"url": "https://x", "slug": "ABC", "expires_in": 1},
    {"url": "https://x", "expires_in": 31536000},
])
def test_create_schema_accepts_valid_fields_without_mutation(body):
    before = dict(body)
    assert validate_create(body) is body
    assert body == before


@pytest.mark.parametrize("body", [
    {}, [], None, {"slug": "abc"}, {"url": "https://x", "other": 1},
    {"url": None}, {"url": 123}, {"url": "ftp://x"},
    {"url": "https://x", "slug": None}, {"url": "https://x", "slug": True},
