def test_create_schema_rejects_unknown_missing_wrong_or_null_fields(body):
    assert_error(400, "invalid_request", lambda: validate_create(body))


def test_clock_schema():
    assert validate_clock({"now": "1969-12-31T23:59:59Z"}) == -1


@pytest.mark.parametrize("body", [
    {}, None, [], {"now": None}, {"now": True}, {"now": 0},
    {"now": "1970-01-01T00:00:00Z", "extra": 1}, {"now": "invalid"},
])
def test_clock_schema_rejects_bad_fields(body):
    assert_error(400, "invalid_request", lambda: validate_clock(body))


@pytest.mark.parametrize("real_time,expected", [(123.999, 123), (-0.001, -1), (-60.5, -61)])
def test_real_clock_floors_seconds(monkeypatch, real_time, expected):
    monkeypatch.setattr(domain.time, "time", lambda: real_time)
    clock = Clock()
    assert not clock.is_fake
    assert clock.now() == expected
    assert type(clock.now()) is int
    assert_error(404, "not_found", lambda: clock.set(0))


def test_fake_clock_frozen_zero_backward_and_not_persisted(monkeypatch):
    monkeypatch.setattr(domain.time, "time", lambda: 123.9)
    clock = Clock(0)
    assert clock.is_fake
    assert clock.now() == 0
    assert clock.set(-1) == -1
    assert clock.now() == -1
    assert clock.set(parse_timestamp("0001-01-01T00:00:00Z")) == -62135596800
    assert clock.now() == -62135596800
    assert Clock(0).now() == 0
    assert Clock().now() == 123


def test_fake_clock_parallel_reads_and_sets_are_whole_seconds():
    clock = Clock(0)
    with ThreadPoolExecutor(max_workers=16) as pool:
        assert list(pool.map(clock.set, range(-50, 50))) == list(range(-50, 50))
        values = list(pool.map(lambda _: clock.now(), range(50)))
    assert all(type(value) is int and -50 <= value < 50 for value in values)
    assert len(set(values)) == 1


def test_rate_limit_retry_after_isolation_next_window_and_restart():
    limiter = RateLimiter(3)
    for _ in range(3):
        assert limiter.check("owner-a", 10) is None
    error = assert_error(429, "rate_limited", lambda: limiter.check("owner-a", 10))
    assert error.headers == {"Retry-After": "50"}
    assert_error(429, "rate_limited", lambda: limiter.check("owner-a", 11))
    assert limiter._counts[("owner-a", 0)] == 5
    limiter.check("owner-b", 10)
    limiter.check("owner-a", 60)
    RateLimiter(3).check("owner-a", 10)


def test_rate_limit_backward_revisits_do_not_reset_windows():
    limiter = RateLimiter(1)
    for now in (10, 70, -10):
        limiter.check("owner", now)
    for now, retry in ((10, "50"), (70, "50"), (-10, "10")):
        error = assert_error(429, "rate_limited", lambda: limiter.check("owner", now))
        assert error.headers == {"Retry-After": retry}


@pytest.mark.parametrize("now,start,retry", [
    (-61, -120, "1"), (-60, -60, "60"), (-1, -60, "1"),
    (0, 0, "60"), (59, 0, "1"), (60, 60, "60"),
])
def test_rate_limit_epoch_alignment_and_retry_arithmetic(now, start, retry):
    limiter = RateLimiter(1)
    limiter.check("owner", now)
    error = assert_error(429, "rate_limited", lambda: limiter.check("owner", now))
    assert error.headers == {"Retry-After": retry}
    assert limiter._counts == {("owner", start): 2}


def test_rate_limit_parallel_count_is_atomic():
    limiter = RateLimiter(17)

    def check(_):
        try:
            limiter.check("owner", 10)
            return "allowed"
        except APIError as error:
            assert error.status == 429
            assert error.headers == {"Retry-After": "50"}
            return "limited"

    with ThreadPoolExecutor(max_workers=50) as pool:
        results = list(pool.map(check, range(50)))
    assert results.count("allowed") == 17
    assert results.count("limited") == 33
    assert limiter._counts[("owner", 0)] == 50


@pytest.mark.parametrize("limit", [0, -1, True, None, 1.5, "3"])
def test_rate_limit_configuration_must_be_positive_integer(limit):
    with pytest.raises(ValueError):
        RateLimiter(limit)


def test_default_rate_limit_is_sixty():
    limiter = RateLimiter()
    for _ in range(60):
        limiter.check("owner", 0)
    assert_error(429, "rate_limited", lambda: limiter.check("owner", 0))

